import {coco,coin} from './art.mjs';
import {LESSONS,compoundProjection} from './learning.mjs';
const styles=`
*{box-sizing:border-box}body{margin:0;background:#edf5fa;color:#14344e;font-family:system-ui,-apple-system,sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer;touch-action:manipulation}button:disabled{opacity:.5;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #ffb938;outline-offset:3px}h1,h2,h3,p{margin:0 0 14px}h1{font-size:20px}h2{font-size:26px;line-height:1.2}h3{font-size:19px}p{line-height:1.6}small{line-height:1.5}.app{max-width:1020px;margin:auto;padding:0 22px 100px}.top{position:sticky;top:0;z-index:20;display:flex;justify-content:space-between;align-items:center;gap:12px;background:#edf5faf5;padding:calc(12px + env(safe-area-inset-top)) 0 12px;border-bottom:1px solid #cde1e9}.top small{display:block;font-size:11px}.top-actions{display:flex;gap:6px}.btn{border:0;border-radius:13px;padding:13px 17px;min-height:46px;font-weight:750;background:#175f97;color:white;display:inline-flex;align-items:center;justify-content:center;gap:8px}.light{background:#e3eff7;color:#153e59}.gold{background:#ffda71;color:#173c54}.danger{background:#9c3c43}.full{width:100%;margin-top:12px}.nav{display:flex;gap:10px;margin:18px 0 24px}.nav .btn{flex:1;background:white;color:#31576d}.nav .active{background:#153e59;color:white}.eyebrow{font-size:11px;font-weight:850;letter-spacing:1px;text-transform:uppercase;margin-bottom:10px;color:#557489}.card{background:white;border:1px solid #dce8ee;border-radius:22px;padding:25px;margin-bottom:18px}.hero{background:#173e5b;color:white;position:relative;overflow:hidden}.hero .eyebrow,.hero small{color:#cce8ee}.hero img{float:right;width:90px;height:115px;object-fit:contain;margin-left:10px}.big{font-size:42px;font-weight:850;letter-spacing:-1px;margin:8px 0 15px}.muted{color:#5b7386;font-size:13px}.note{background:#e8f5f2;border-left:4px solid #39a894;padding:14px 17px;border-radius:0 12px 12px 0;line-height:1.65;margin:16px 0;font-size:14px}.warning{background:#fff5dd;border-color:#d99c20}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.metric{background:#f0f6fa;border-radius:16px;padding:15px}.metric span{font-size:12px;display:block}.metric strong{font-size:22px;display:block;margin-top:7px;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.tile{border:0;text-align:left;border-radius:22px;background:#175f97;color:white;padding:25px;min-height:155px}.tile:nth-child(2){background:#16756c}.tile:nth-child(3){background:#6746a3}.tile:nth-child(4){background:#9a4b27}.tile b{display:block;font-size:23px;margin-bottom:10px}.tile small{display:block;font-size:14px}.asset{display:flex;flex-direction:column;align-items:flex-start;text-align:left;background:white;border:1px solid #dce8ee;border-radius:20px;padding:22px;color:inherit;min-width:0}.asset .price{font-size:25px;font-weight:800;margin:12px 0 6px}.badge{border-radius:9px;background:#eaf2f7;padding:5px 8px;font-size:11px;font-weight:750;display:inline-block;margin-bottom:12px}.asset p{font-size:14px}.asset .more{margin-top:auto;font-size:13px;font-weight:800;color:#176693}.positive{color:#08785a}.negative{color:#b83749}.line{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:14px 0;border-bottom:1px solid #e3edf3}.line:last-child{border-bottom:0}.line>span{min-width:0}.line small{display:block;color:#5b7386;font-size:12px}.line strong{white-space:nowrap}.field{display:block;font-weight:650;margin:18px 0;font-size:14px}.field input,.field select,.field textarea{width:100%;border:1px solid #becfdb;border-radius:12px;background:white;color:#173e59;padding:13px;margin-top:8px;min-height:48px}.field textarea{min-height:90px}.choices{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0}.choices .btn{flex:1}.pill{background:#eaf2f7;border:0;border-radius:12px;padding:12px 14px;font-weight:750;color:#234d68}.pill.active{background:#173e5b;color:white}.source{display:block;width:100%;padding:10px;border:1px solid #ccdce7;border-radius:8px;font-size:12px;color:#47657d}.footer{color:#58768b;font-size:12px;text-align:center;margin-top:28px;line-height:1.6}.status{position:fixed;bottom:90px;left:50%;transform:translateX(-50%);z-index:90;background:#173e5b;color:white;border-radius:14px;padding:14px 18px;max-width:90vw;box-shadow:0 8px 30px #1234}.status:empty{display:none}.modal-wrap{position:fixed;inset:0;background:#0e233bb0;z-index:50;display:grid;place-items:center;padding:20px}.modal{background:white;padding:25px;border-radius:22px;width:min(640px,100%);max-height:90dvh;overflow:auto}.modal-head{display:flex;gap:8px;justify-content:space-between;margin-bottom:20px}.empty{text-align:center;padding:40px 20px}.bar{display:flex;height:28px;overflow:hidden;border-radius:8px;background:#dbe8ef;margin:15px 0}.bar span{display:block;height:100%}.lesson{margin-top:18px}.lesson summary{font-size:18px;font-weight:750;cursor:pointer;padding:7px 0}.lesson[open] summary{margin-bottom:15px}.table{width:100%;border-collapse:collapse;font-size:13px}.table td,.table th{text-align:right;padding:11px 5px;border-bottom:1px solid #dce7ed}.table td:first-child,.table th:first-child{text-align:left}input[readonly]{max-width:100%}.sr-only{position:absolute;clip:rect(0,0,0,0);width:1px;height:1px;overflow:hidden}#content{scroll-margin-top:100px}
@media(max-width:620px){.app{padding:0 12px 105px}.top{gap:6px}.top h1{font-size:15px}.top small{font-size:9px}.top .btn{font-size:10px;padding:9px 8px;min-height:44px}.top-actions{gap:4px}.nav{position:fixed;bottom:0;left:0;right:0;background:white;margin:0;padding:10px 8px calc(10px + env(safe-area-inset-bottom));z-index:30;gap:5px;border-top:1px solid #d7e5ee}.nav .btn{font-size:11px;padding:12px 5px;min-height:52px}#content{padding-top:18px}.card{padding:20px;border-radius:18px}.hero img{width:66px;height:90px}.big{font-size:35px}h2{font-size:24px}.grid{gap:10px}.asset{padding:16px}.asset h3{font-size:17px}.asset p{font-size:13px}.asset .price{font-size:22px}.tile{padding:19px 15px;min-height:150px}.tile b{font-size:20px}.tile small{font-size:12px}.metrics{grid-template-columns:1fr;gap:8px}.metric{display:flex;justify-content:space-between;align-items:center;gap:8px}.metric strong{margin:0;font-size:21px}.line{flex-wrap:wrap}.modal{padding:20px}.modal-wrap{padding:12px}.choices .btn{font-size:12px;padding:12px}.footer{font-size:11px}}
@media(max-width:350px){.grid{grid-template-columns:1fr}.top h1{font-size:13px}.top small{display:none}}
`;
function app(){
 const root=document.getElementById('app'),channel=window.BANK_CHANNEL;let data=null,view='home',assetId=null,group='stocks',search='',history=[],seq=0,busy=false,parentSession=null,parentTimer=null,modalKind=null;
 const pending=new Map(),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=(n,d=2)=>Number(n||0).toLocaleString('es-ES',{maximumFractionDigits:d}),money=n=>num(n/100)+' €',date=t=>new Date(t).toLocaleString('es-ES',{timeZone:'UTC',day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}),now=()=>data?.serverTime||Date.now();
 const cat=id=>data.catalog.find(c=>c.id===id),activeParent=()=>parentSession&&parentSession.expires>Date.now();
 const fresh=p=>!!p&&p.eur>0&&p.at<=now()&&now()-p.at<5*86400000&&p.fetchedAt<=now()&&now()-p.fetchedAt<36*3600000;
 let lab={initial:100,monthly:100,years:10,annualPct:5};
 function api(path,body){return new Promise((resolve,reject)=>{const id=++seq,timer=setTimeout(()=>{pending.delete(id);reject(Error('La conexión está tardando. Vuelve a intentarlo.'))},25000);pending.set(id,{resolve,reject,timer});parent.postMessage({cocoBank:true,channel,id,path,body},'*')})}
 addEventListener('message',e=>{if(e.source!==parent||e.data?.channel!==channel||!e.data?.reply)return;const p=pending.get(e.data.id);if(p){clearTimeout(p.timer);pending.delete(e.data.id);e.data.error?p.reject(Error(e.data.error)):p.resolve(e.data.data)}});
 function notify(text){const el=document.getElementById('status');if(el)el.textContent=text}
 function snap(){return {view,assetId,group,search}}
 function go(next,id=null){history.push(snap());view=next;assetId=id;render();scrollTo(0,0)}
 function back(){if(document.getElementById('modal')?.innerHTML){closeModal();return}const p=history.pop();if(!p){parent.postMessage({cocoBank:true,channel,close:true},'*');return}({view,assetId,group,search}=p);render();scrollTo(0,0)}
 function closeModal(){document.getElementById('modal')?.replaceChildren();modalKind=null}
 function modal(html){document.getElementById('modal').innerHTML=`<div class="modal-wrap"><section class="modal" role="dialog" aria-modal="true" aria-label="Coco te acompaña"><div class="modal-head"><button class="btn light" data-back>← Volver</button><button class="btn light" data-close>Menú principal</button></div>${html}</section></div>`;document.querySelector('.modal input,.modal button')?.focus()}
 async function send(action,success){if(busy)return false;busy=true;const a={...action,requestId:crypto.randomUUID(),parentToken:activeParent()?parentSession.token:undefined};if(['buy','deposit','employer'].includes(a.type)&&a.amount!==undefined)a.amount=Number(a.amount)/10;if(a.type==='setup'){a.config={...a.config,experience:'investing',mode:'continuous',salary:Number(a.config.salary)/10,initial:Number(a.config.initial)/10,reserve:0,expenses:{}}}
 try{data=await api('/action',a);closeModal();if(a.type==='setup'){parentSession=null;view='home';api('/action',{type:'parent_lock'}).catch(()=>{})}render();notify(success||'Guardado.');return true}catch(e){notify(e.message);return false}finally{busy=false;document.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false)}}
 function shell(content){return `<main class="app"><header class="top"><div class="top-actions"><button class="btn light" data-back>← Volver</button><button class="btn light" data-close>Menú principal</button></div><div><h1>Coco Bank</h1><small>Aprende a invertir · Dinero de juego</small></div><button class="btn light" data-parent>Adultos</button></header><nav class="nav" aria-label="Secciones">${[['home','Mi dinero'],['invest','Invertir'],['portfolio','Mi cartera'],['learn','Aprender']].map(([id,title])=>`<button class="btn ${view===id?'active':''}" data-go="${id}" ${view===id?'aria-current="page"':''}>${title}</button>`).join('')}</nav><div id="content">${content}</div><footer class="footer">Simulación educativa. No hay compras ni dinero real.<br>Precios de referencia de mercado, no cotizaciones en directo. No son recomendaciones de inversión.</footer></main><div id="modal"></div><div id="status" class="status" role="status" aria-live="polite"></div>`}
 function onboarding(){const s=data.state;if(!s)return `<section class="card hero"><img src="${window.ART.coco}" alt="Coco"><div class="eyebrow">Un pequeño inversor, grandes preguntas</div><h2>¿Qué harás con tu dinero?</h2><p>Cada mes recibirás una asignación virtual. Tú decides qué invertir y qué dejar en la cuenta.</p></section><section class="card"><h2>Primero, crea tu cuenta</h2><form id="account"><label class="field">Tu nombre<input name="name" maxlength="40" required autocomplete="off"></label><button class="btn full" type="submit">Crear mi cuenta</button></form></section>`;if(!s.config||!data.parent?.configured)return `<section class="card"><h2>Prepara tu asignación con un adulto</h2><p>El adulto elige cuánto dinero de juego recibes cada mes. No tendrás que pagar alquiler ni facturas.</p><button class="btn full" data-parent>Adulto · preparar la cuenta</button></section>`;return `<section class="card hero"><img src="${window.ART.coco}" alt="Coco"><h2>${s.journey?.funded?'Conoce tu cuenta':'Tu primera asignación está lista'}</h2><p>Recibirás ${money(s.config.salary)} virtuales al mes. Puedes aprender, invertir una parte o dejar dinero en la cuenta.</p><button class="btn gold full" data-receive>${s.journey?.funded?'Entendido · empezar':'Recibir mi asignación'}</button></section>`}
 function nextPayday(){const c=data.state.config,start=new Date(c.payrollStartsAt||c.startsAt),today=new Date(now());for(let i=0;i<2;i++){const y=today.getUTCFullYear(),m=today.getUTCMonth()+i,d=Math.min(start.getUTCDate(),new Date(Date.UTC(y,m+1,0)).getUTCDate()),at=Date.UTC(y,m,d);if(at>now())return at}return null}
 function home(){const s=data.state,i=data.summary,next=nextPayday();return `<section class="card hero"><img src="${window.ART.coco}" alt="Coco"><div class="eyebrow">Hola, ${esc(s.account.name)}</div><p>Dinero disponible para decidir</p><div class="big">${money(i.available)}</div><small>Asignación mensual: ${money(s.config.salary)}${next?' · Próxima: '+date(next):''}</small><button class="btn gold full" data-go="invest">Explorar mis opciones →</button></section><section class="card"><h2>Tu dinero, sin confusiones</h2><div class="metrics"><div class="metric"><span>En tu cuenta</span><strong>${money(s.cash)}</strong></div><div class="metric"><span>En inversiones y cartera</span><strong>${money(i.value)}</strong></div><div class="metric"><span>Ganancia o pérdida de inversión</span><strong class="${i.profit<0?'negative':'positive'}">${money(i.profit)}</strong></div></div><p class="muted" style="margin-top:16px">La asignación que recibes no es una ganancia de inversión. ${i.earmarked?money(i.earmarked)+' están reservados para compras pendientes.':''}</p></section><div class="grid"><button class="tile" data-go="invest"><b>¿En qué invierto?</b><small>20 empresas, fondos, bonos y plazos fijos.</small></button><button class="tile" data-go="portfolio"><b>¿Cómo va mi dinero?</b><small>Consulta tus inversiones y tus decisiones.</small></button><button class="tile" data-go="lab"><b>La fuerza del tiempo</b><small>Experimenta con el interés compuesto.</small></button><button class="tile" data-go="learn"><b>Entender la bolsa</b><small>Aprende antes de tomar una decisión.</small></button></div><div class="note">También puedes no invertir hoy. El dinero que dejas en la cuenta sigue disponible, sin intereses en este juego.</div>`}
 function quote(c){const p=data.market.prices[c.id];return p?`<div class="price">${money(p.eur*100)}</div><small>${num(p.local)} ${esc(p.currency)} · por título</small><p class="muted">Referencia: ${date(p.at)} UTC<br>${fresh(p)?'Dato disponible para simular':'Dato antiguo: compras y ventas en pausa'}</p>`:'<p class="note warning">Esperando una cotización real. No inventamos precios.</p>'}
 function marketInfo(){const m=data.market;return `<details class="card"><summary>Fechas y fuentes de los datos</summary><p class="muted" style="margin-top:15px">Consulta programada diaria a las 12:00 y 22:15 UTC. Último intento: ${m.updatedAt?date(m.updatedAt)+' UTC':'pendiente'}. Cada ficha muestra la fecha de su precio, que puede ser anterior.</p><p class="muted">Acciones y ETF: cierres de Yahoo Finance. Conversión a euros y referencia €STR: Banco Central Europeo. No son precios en tiempo real. Las compras y ventas esperan una observación posterior a la orden. En festivos y fines de semana pueden tardar.</p><p class="muted">Simulamos fracciones sin comisiones de compraventa ni impuestos. Los costes internos de los fondos están reflejados en sus precios. Los dividendos se simplifican; las divisas también pueden cambiar el resultado.</p>${m.errors?.length?`<p class="note warning">Hay fuentes pendientes: ${m.errors.map(esc).join(' · ')}</p>`:''}</details>`}
 function invest(){const categories=[['stocks','Acciones · 20'],['funds','Fondos'],['bonds','Bonos'],['deposit','Plazo fijo']];const list=data.catalog.filter(c=>c.group===group&&(!search||(c.name+' '+c.symbol+' '+c.sector).toLowerCase().includes(search.toLowerCase())));return `<section class="card"><div class="eyebrow">Tú eliges</div><h2>¿En qué quieres invertir?</h2><p>Disponible: <strong>${money(data.summary.available)}</strong>. Abre una ficha y entiende cómo funciona antes de comprar.</p><div class="choices">${categories.map(([id,title])=>`<button class="pill ${group===id?'active':''}" data-group="${id}" aria-pressed="${group===id}">${title}</button>`).join('')}</div>${group==='stocks'?'<form id="search"><label class="field">Buscar una empresa<input name="search" value="'+esc(search)+'" placeholder="Apple, Tesla, Waymo…"></label><button class="btn light" type="submit">Buscar</button></form><p class="muted">Waymo está dentro de Alphabet. No tiene una acción pública independiente.</p>':group==='funds'?'<p>Un fondo agrupa inversiones. Aquí utilizamos ETF reales: fondos que cotizan en bolsa.</p>':group==='bonds'?'<p>Un bono es dinero prestado a un emisor. Aquí lo practicas mediante fondos de deuda reales, no comprando un bono individual.</p>':''}</section>${group==='deposit'?depositPage():`<div class="grid">${list.map(c=>`<button class="asset" data-asset="${c.id}"><span class="badge">${esc(c.symbol)} · ${esc(c.sector)}</span><h3>${esc(c.name)}</h3><p>${esc(c.what)}</p>${quote(c)}<span class="more">Entender y decidir →</span></button>`).join('')}</div>${!list.length?'<p class="card">No encontré esa empresa. Prueba con otro nombre.</p>':''}`}${marketInfo()}`}
 function detail(){const c=cat(assetId);if(!c)return invest();return `<section class="card"><span class="badge">${esc(c.kind)} · ${esc(c.symbol)}</span><h2>${esc(c.name)}</h2>${quote(c)}<h3>¿Qué hace?</h3><p>${esc(c.what||c.lesson)}</p><h3>¿Por qué tiene valor en bolsa?</h3><p>${esc(c.value||'Su precio depende de compradores y vendedores.')}</p><div class="note">El precio de una acción no es el valor de toda la empresa. En una clase de acciones, precio × número de acciones da su capitalización; algunas empresas tienen varias clases. Una acción más barata no implica una empresa más barata.</div><div class="grid"><section><h3>Podría subir si…</h3><p>${esc(c.up||'aumenta la demanda.')}</p></section><section><h3>Podría bajar si…</h3><p>${esc(c.down||'disminuye la demanda.')}</p></section></div><p class="muted">Son ejemplos de factores posibles, no explicaciones comprobadas de la variación de hoy. Las buenas noticias pueden estar ya incluidas en el precio.</p>${c.id==='GOOGL'?'<div class="note">Waymo desarrolla conducción autónoma. Aquí puedes simular comprar Alphabet, que incluye muchos negocios: no es una inversión exclusiva en Waymo.</div>':''}${c.id==='SAMSUNG'?'<div class="note">Cotiza en wones. Aunque el precio coreano no cambie, tu valor en euros puede cambiar con la divisa.</div>':''}<button class="btn full" data-lesson="${c.id}" ${c.group==='legacy'?'disabled':''}>${data.state.lessons.includes(c.id)?'Elegir cuánto invertir':'Entender el riesgo y elegir cantidad'}</button>${c.source?`<details style="margin-top:18px"><summary>Fuente del negocio o fondo</summary><label class="field">Enlace para consultar con un adulto<input class="source" readonly value="${esc(c.source)}"></label></details>`:''}</section>`}
 function depositPage(){const r=data.market.rate,ok=r&&Number.isFinite(r.annualPct)&&r.annualPct>=0&&now()-r.fetchedAt<36*3600000&&now()-Date.parse(r.date)<7*86400000;return `<section class="card"><span class="badge">Plazo fijo educativo</span><h2>Dejar dinero durante un tiempo</h2><p>Eliges 30, 90 o 180 días. El dinero queda bloqueado hasta esa fecha. Al terminar, el capital y el interés pasan al efectivo de tu cartera.</p><div class="big">${r?num(r.annualPct,3)+' % anual':'Esperando referencia'}</div><p class="muted">${r?'Referencia BCE €STR del '+esc(r.date)+'.':''} Es un tipo real de mercado usado como ejemplo, no una oferta de un banco ni una garantía real.</p><div class="note">El interés es proporcional a los días y se fija al abrir el plazo. Al vencer, puedes volver a invertir capital e intereses para practicar la capitalización. No se reinvierte automáticamente.</div>${!ok?'<p class="note warning">La referencia no está disponible o está antigua. Nuevos plazos en pausa.</p>':''}<button class="btn full" data-lesson="DEPOSIT" ${!ok?'disabled':''}>Entender y elegir un plazo</button></section>`}
 function portfolio(){const s=data.state,i=data.summary,held=Object.entries(s.holdings),total=i.value,groupValues={};for(const [id,h]of held){const c=cat(id),v=h.qty*(data.market.prices[id]?.eur||h.lastEur)*100;groupValues[c?.sector||'Otros']=(groupValues[c?.sector||'Otros']||0)+v}const max=total?Math.max(0,...Object.values(groupValues))/total:0;return `<section class="card"><h2>Mi cartera</h2><div class="metrics"><div class="metric"><span>Valor de cartera</span><strong>${money(i.value)}</strong></div><div class="metric"><span>Aportado menos retirado</span><strong>${money(i.contributed-i.withdrawn)}</strong></div><div class="metric"><span>Ganancia / pérdida</span><strong class="${i.profit<0?'negative':'positive'}">${money(i.profit)}</strong></div></div><p class="muted" style="margin-top:15px">Rentabilidad por participaciones: ${num(i.returnPct)} %. Las aportaciones nuevas no se cuentan como ganancias. Los valores pueden ser antiguos: revisa sus fechas.</p>${max>.6?'<div class="note warning">Más del 60 % de tu cartera está en un mismo sector. Piensa qué pasaría si ese sector cae. No tienes que vender: primero entiende el riesgo.</div>':''}<button class="btn light full" data-refresh>Actualizar valores</button></section><section class="card"><h2>Mis acciones y fondos</h2>${held.length?held.map(([id,h])=>{const c=cat(id),p=data.market.prices[id];return `<div class="line"><span><strong>${esc(c?.name||id)}</strong><small>${num(h.qty,6)} títulos · ${money(h.qty*(p?.eur||h.lastEur)*100)}</small><small>${p?date(p.at)+' UTC':'Último valor conocido'}${!fresh(p)?' · dato antiguo':''}</small></span><button class="btn light" data-sell="${id}" ${!fresh(p)?'disabled':''}>Vender</button></div>`}).join(''):'<p>Todavía no tienes acciones ni fondos. Puedes explorar sin comprar.</p>'}</section><section class="card"><h2>Mis plazos fijos</h2>${s.deposits.length?s.deposits.map(d=>`<div class="line"><span>${money(d.principal)} al ${num(d.rate,3)} % anual<small>Vence: ${date(d.endsAt)} UTC</small></span><strong>${money(d.principal+Math.floor(d.principal*d.rate/100*Math.max(0,Math.min(now(),d.endsAt)-d.startsAt)/86400000/365))}</strong></div>`).join(''):'<p>No tienes plazos abiertos.</p>'}${s.investmentCash?`<div class="note">Efectivo en cartera: <strong>${money(s.investmentCash)}</strong>. Incluye intereses o dividendos recibidos y plazos vencidos.</div><button class="btn full" data-withdraw>Pasar a mi cuenta para poder reinvertir</button>`:''}</section>${s.orders.length?`<section class="card"><h2>Operaciones pendientes</h2><p class="muted">Esperan un precio posterior a tu decisión. No se ejecutan con un cierre que ya conocías.</p>${s.orders.map(o=>`<div class="line"><span>${o.side==='buy'?'Compra':'Venta'} · ${esc(cat(o.asset)?.name||o.asset)}<small>${o.side==='buy'?money(o.amount):'Todos mis títulos'}</small></span><button class="btn light" data-cancel="${o.id}">Cancelar</button></div>`).join('')}</section>`:''}<details class="card"><summary>Mi diario: por qué invertí</summary>${(s.reflections||[]).map(x=>`<div class="line"><span><b>${esc(cat(x.asset)?.name||'Plazo fijo')}</b><small>${date(x.at)}</small><p>${esc(x.reason)}</p></span></div>`).join('')||'<p>Tus razones aparecerán aquí al invertir.</p>'}</details><details class="card"><summary>Entradas y salidas de dinero</summary>${s.ledger.slice(0,60).map(x=>`<div class="line"><span>${esc(x.text)}<small>${date(x.at)}</small></span><strong>${x.amount?money(x.amount):'—'}</strong></div>`).join('')}</details>${marketInfo()}`}
 function learn(){return `<section class="card"><div class="eyebrow">Entender antes de decidir</div><h2>La bolsa, paso a paso</h2><p>Aquí cuenta lo que aprendes. No hay premios por comprar más ni por asumir más riesgo.</p><button class="btn gold full" data-go="lab">Probar el laboratorio de interés compuesto</button></section>${window.LESSONS.map(l=>`<details class="card lesson"><summary>${data.state.lessons.includes(l.id)?'✓ ':''}${esc(l.title)}</summary><p>${esc(l.text)}</p><div class="note">${esc(l.example)}</div><h3>${esc(l.question)}</h3>${l.options.map(([id,t])=>`<button class="btn light full" data-answer="${l.id}:${id}">${esc(t)}</button>`).join('')}</details>`).join('')}<section class="card"><h3>Palabras que ya puedes entender</h3><p><b>Dividendo:</b> dinero que una empresa puede repartir a sus accionistas. No está garantizado y no es dinero gratis: el precio suele ajustarse al reparto.</p><p><b>Inflación:</b> con el tiempo, los precios de las cosas pueden subir. Tener la misma cantidad de euros no garantiza comprar lo mismo.</p><p><b>Liquidez:</b> facilidad para convertir una inversión en dinero disponible.</p><p><b>Interés y rentabilidad:</b> un plazo puede fijar un tipo; una acción no promete un rendimiento.</p><p><b>Comisiones e impuestos:</b> en la vida real pueden reducir lo que ganas. Esta simulación no los descuenta al operar.</p></section>`}
 function laboratory(){const p=window.compoundProjection(lab.initial,lab.monthly,lab.years,lab.annualPct),base=Math.max(p.value,p.contributed,1);return `<section class="card"><span class="badge">Laboratorio · números inventados</span><h2>¿Qué cambia cuando dejas pasar el tiempo?</h2><p>Prueba diferentes aportaciones, años y rendimientos. Esto no cambia tu cartera ni predice el mercado.</p><form id="compound"><div class="grid">${[['initial','Dinero inicial (€)',0,1000000,1],['monthly','Aportación mensual (€)',0,1000000,1],['years','Años',1,40,1],['annualPct','Rendimiento anual supuesto (%)',-20,20,.1]].map(([id,label,min,max,step])=>`<label class="field">${label}<input type="number" name="${id}" min="${min}" max="${max}" step="${step}" value="${lab[id]}" required></label>`).join('')}</div><button class="btn full" type="submit">Ver qué pasaría</button></form></section><section class="card"><h2>${num(p.value)} € al final del ejemplo</h2><div class="bar" aria-label="Aportaciones y resultado hipotético"><span style="width:${p.contributed/base*100}%;background:#175f97"></span>${p.gain>0?`<span style="width:${p.gain/base*100}%;background:#22a38d"></span>`:''}</div><p>Aportado por ti: <b>${num(p.contributed)} €</b><br>Ganancia o pérdida hipotética: <b>${num(p.gain)} €</b></p><div class="note warning">Supone siempre el mismo rendimiento, capitalización mensual (tipo anual dividido entre 12) y aportaciones al final de cada mes. En la bolsa los rendimientos cambian y puedes perder dinero. No incluye inflación, impuestos ni comisiones.</div><table class="table"><thead><tr><th>Año</th><th>Aportado</th><th>Valor supuesto</th></tr></thead><tbody>${p.series.filter((x,i)=>i===0||x.year%5===0||x.year===lab.years).map(x=>`<tr><td>${x.year}</td><td>${num(x.contributed)} €</td><td>${num(x.value)} €</td></tr>`).join('')}</tbody></table><p class="muted" style="margin-top:15px">Ejemplo sencillo: 100 € al 5 % serían 105 € tras un año; reinvirtiendo, 110,25 € tras dos años con el mismo 5 %. En acciones ese 5 % no está asegurado.</p></section>`}
 function adult(){if(!activeParent())return '<section class="card"><h2>Área de adultos</h2><button class="btn" data-parent>Entrar con PIN</button></section>';if(!data.state.config)return `<section class="card"><h2>Solo una asignación mensual</h2><p>Importes ficticios. El niño no tiene gastos de casa ni un objetivo obligatorio.</p><form id="setup"><label class="field">Dinero cada mes (€ virtuales)<input name="salary" type="number" min="0.01" max="1000000" step="0.01" value="100" required></label><label class="field">Dinero inicial adicional (€ virtuales)<input name="initial" type="number" min="0" max="1000000" step="0.01" value="0" required></label><button type="submit" class="btn full">Preparar su asignación</button></form></section>`;return `<section class="card"><h2>Asignación mensual</h2><p>Lo ya recibido se conserva. Los cambios se aplican a próximos pagos.</p><form id="salary"><label class="field">Euros virtuales al mes<input name="amount" type="number" min="0.01" max="1000000" step="0.01" value="${data.state.config.salary/100}" required></label><button type="submit" class="btn full">Guardar asignación</button></form><button class="btn light full" data-lock>Terminar y volver al niño</button><button class="btn light full" data-recover>Cambiar o recuperar PIN</button></section>`}
 function render(){if(!data)return;const ready=data.state?.config&&data.parent?.configured&&data.state.journey?.funded&&data.state.journey?.acknowledged;const body=view==='adult'?adult():!ready?onboarding():view==='invest'?invest():view==='detail'?detail():view==='portfolio'?portfolio():view==='learn'?learn():view==='lab'?laboratory():home();root.innerHTML=shell(body);wire()}
 function pin(recover=false){if(!data.state)return notify('Primero crea la cuenta del niño.');const creating=recover||!data.parent.configured;modalKind='pin';modal(`<h2>${creating?'Crea el PIN del adulto':'Acceso de adulto'}</h2><p>${creating?'Confirma la contraseña de tu cuenta de Coco. El PIN protege la asignación mensual.':'Introduce tu PIN de seis números.'}</p><form id="pin">${creating?'<label class="field">Contraseña de Coco<input type="password" name="password" autocomplete="current-password" required maxlength="256"></label>':''}<label class="field">PIN de 6 números<input type="password" name="pin" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required autocomplete="off"></label>${creating?'<label class="field">Repite el PIN<input type="password" name="repeat" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label>':''}<button class="btn full" type="submit">Entrar</button></form>${!creating?'<button class="btn light full" data-recover>He olvidado el PIN</button>':''}`);document.getElementById('pin').onsubmit=async e=>{e.preventDefault();if(busy)return;const f=new FormData(e.target);if(creating&&f.get('pin')!==f.get('repeat'))return notify('Los dos PIN deben ser iguales.');busy=true;try{parentSession=await api('/action',{type:creating?'parent_set_pin':'parent_unlock',pin:f.get('pin'),password:creating?f.get('password'):undefined});clearTimeout(parentTimer);parentTimer=setTimeout(()=>{parentSession=null;if(view==='adult')go('home')},Math.max(0,parentSession.expires-Date.now()));data=await api('/state');closeModal();go('adult')}catch(err){notify(err.message);e.target.reset()}finally{busy=false}}}
 function lesson(id){const c=cat(id),s=data.state;if(s.lessons.includes(id))return trade(id);const answer=id==='DEPOSIT'?'locked':c.answer,question=id==='DEPOSIT'?'¿Puedes usar ese dinero antes del vencimiento?':answer==='rates'?'¿Puede bajar un fondo de bonos?':answer==='currency'?'¿El cambio de moneda puede afectar a tu valor en euros?':answer==='diversify'?'¿Un fondo diversificado puede perder valor?':'¿Una empresa famosa puede perder valor en bolsa?',correct=id==='DEPOSIT'?'No. En este juego queda bloqueado hasta el vencimiento.':answer==='rates'?'Sí. Por los tipos de interés, la divisa y otros riesgos.':answer==='currency'?'Sí. El cambio de moneda también influye.':answer==='diversify'?'Sí. Repartir el riesgo no elimina todas las pérdidas.':'Sí. No hay ganancias garantizadas.';modal(`<h2>Antes de invertir</h2><p>${esc(c?.lesson||'Un plazo fija la fecha y el tipo al abrirlo. Es dinero de juego.')}</p><h3>${question}</h3><button class="btn full" data-answer="${id}:${answer}">${correct}</button><button class="btn light full" data-answer="${id}:wrong">No hay ningún riesgo y siempre ganaré.</button>`)}
 function trade(id){const deposit=id==='DEPOSIT',c=cat(id);if(!deposit&&!fresh(data.market.prices[id]))return notify('Esperamos una cotización reciente antes de operar.');modal(`<h2>${deposit?'Abrir plazo fijo educativo':esc(c.name)}</h2><p>Puedes usar hasta ${money(data.summary.available)}.</p><form id="trade"><label class="field">Cantidad (€ virtuales)<input name="amount" type="number" min="0.01" max="${data.summary.available/100}" step="0.01" required placeholder="Por ejemplo, 10"></label>${deposit?'<label class="field">Duración<select name="term"><option value="30">30 días</option><option value="90">90 días</option><option value="180">180 días</option></select></label>':''}<label class="field">¿Por qué eliges esta inversión?<textarea name="reason" minlength="8" maxlength="240" required placeholder="Quiero aprender cómo…"></textarea></label><p class="muted">${deposit?'Tu dinero queda bloqueado hasta el vencimiento.':'Simulamos una fracción al próximo precio disponible posterior a la orden. Puede tardar y el precio puede bajar.'}</p><button class="btn full" type="submit">${deposit?'Abrir plazo virtual':'Confirmar compra virtual'}</button></form>`);document.getElementById('trade').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);send({type:deposit?'deposit':'buy',asset:id,amount:f.get('amount'),term:f.get('term'),reason:f.get('reason')},deposit?'Plazo abierto. Puedes seguirlo en Mi cartera.':'Orden guardada. Espera al siguiente precio.')}}
 function wire(){const bind=(id,fn)=>{const f=document.getElementById(id);if(f)f.onsubmit=e=>{e.preventDefault();fn(Object.fromEntries(new FormData(f)))}};bind('account',f=>send({type:'open_account',name:f.name},'Cuenta creada. Ahora prepara la asignación con un adulto.'));bind('setup',f=>send({type:'setup',config:f},'Asignación preparada. Ya puede recibir su dinero.'));bind('salary',f=>send({type:'employer',decision:'salary',amount:f.amount,reason:'Asignación mensual ajustada por el adulto.'},'Guardado para los próximos meses.'));bind('search',f=>{search=f.search;render()});bind('compound',f=>{try{const next=Object.fromEntries(Object.entries(f).map(([k,v])=>[k,Number(v)]));window.compoundProjection(next.initial,next.monthly,next.years,next.annualPct);lab=next;render()}catch(e){notify(e.message)}})}
 root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-close')){parent.postMessage({cocoBank:true,channel,close:true},'*');return}if(b.hasAttribute('data-back'))return back();if(b.hasAttribute('data-parent'))return activeParent()?go('adult'):pin();if(b.hasAttribute('data-recover'))return pin(true);if(b.hasAttribute('data-lock')){await api('/action',{type:'parent_lock'}).catch(()=>{});parentSession=null;go('home');return}if(b.dataset.go)return go(b.dataset.go);if(b.dataset.group){group=b.dataset.group;search='';render();return}if(b.dataset.asset)return go('detail',b.dataset.asset);if(b.hasAttribute('data-receive'))return send({type:data.state.journey?.funded?'ack_funds':'receive'},'Tu dinero está listo. Tú decides.');if(b.dataset.lesson)return lesson(b.dataset.lesson);if(b.dataset.answer){const [asset,answer]=b.dataset.answer.split(':');if(await send({type:'lesson',asset,answer},'¡Entendido!')){if(!window.LESSONS.some(l=>l.id===asset))trade(asset)}return}if(b.dataset.sell){modal(`<h2>¿Vender tu posición en ${esc(cat(b.dataset.sell)?.name||b.dataset.sell)}?</h2><p>Se venderán todos tus títulos al siguiente precio de referencia posterior a la orden. El importe puede variar.</p><button class="btn full" data-confirm-sell="${b.dataset.sell}">Confirmar venta virtual</button>`);return}if(b.dataset.confirmSell)return send({type:'sell',asset:b.dataset.confirmSell},'Venta en espera.');if(b.dataset.cancel)return send({type:'cancel',orderId:b.dataset.cancel},'Orden cancelada.');if(b.hasAttribute('data-withdraw'))return send({type:'withdraw'},'El dinero está en tu cuenta. Puedes decidir si reinvertirlo.');if(b.hasAttribute('data-refresh')){try{data=await api('/state');render();notify('Valores disponibles actualizados. Cada ficha indica su fecha.')}catch(e){notify(e.message)}}});
 async function load(){try{data=await api('/state');render()}catch(e){root.innerHTML=shell(`<section class="card"><h2>No se pudo abrir tu banco</h2><p>${esc(e.message)}</p><button class="btn" id="retry">Volver a intentar</button></section>`);document.getElementById('retry').onclick=load}}load();
}
export function renderApp(){return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; script-src \'unsafe-inline\'; style-src \'unsafe-inline\'; img-src data:; connect-src \'none\'; base-uri \'none\'; form-action \'none\'"><title>Coco Bank · Aprende a invertir</title><style>'+styles+'</style></head><body><div id="app"><section class="card"><p>Cargando Coco Bank…</p><button class="btn light" data-back>Volver</button><button class="btn light" data-close>Menú principal</button></section></div><script>window.BANK_CHANNEL="__BANK_CHANNEL__";window.ART='+JSON.stringify({coco,coin})+';window.LESSONS='+JSON.stringify(LESSONS)+';window.compoundProjection='+compoundProjection.toString()+';('+app.toString()+')();</script></body></html>'}
